+package com.example;
+
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.provider.ListDataProvider;
+import com.vaadin.flow.router.BeforeEnterEvent;
+import com.vaadin.flow.router.BeforeEnterObserver;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.shared.Registration;
+
+import java.util.regex.Pattern;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeEnterObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+$");
+
+    private static final String ERR_NAME_REQUIRED = "Name is required";
+    private static final String ERR_INVALID_EMAIL = "Enter a valid e-mail address";
+    private static final String ERR_EMAIL_OR_PHONE = "Give an e-mail address or a phone number";
+    private static final String ERR_MESSAGE_REQUIRED = "Message is required";
+    private static final String ERR_MESSAGE_TOO_LONG = "Message must be at most 500 characters";
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> grid = new Grid<>();
+
+    private Registration leaveRegistration;
+
+    public ContactView() {
+        setPadding(true);
+        setSpacing(true);
+        setMaxWidth("640px");
+
+        grid.addColumn(Message::getName).setHeader("Name").setKey("name");
+        grid.addColumn(Message::getEmail).setHeader("Email").setKey("email");
+        grid.addColumn(Message::getPhone).setHeader("Phone").setKey("phone");
+        grid.addColumn(Message::getMessage).setHeader("Message").setKey("message");
+        grid.setEmptyStateText("No messages yet.");
+
+        name.setWidthFull();
+        email.setWidthFull();
+        phone.setWidthFull();
+        message.setWidthFull();
+        message.setMinRows(5);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1));
+
+        sendButton.addClickListener(e -> sendMessage());
+        addSendEnabler(name);
+        addSendEnabler(email);
+        addSendEnabler(phone);
+        addSendEnabler(message);
+        Shortcuts.addShortcutListener(this, e -> sendMessage(), Key.ENTER);
+
+        add(
+                new H1("Contact"),
+                new RouterLink("About", AboutView.class),
+                form,
+                sendButton,
+                grid
+        );
+    }
+
+    private void addSendEnabler(HasValue<?, String> field) {
+        field.addValueChangeListener(e -> sendButton.setEnabled(true));
+    }
+
+    @Override
+    public void beforeEnter(BeforeEnterEvent event) {
+        refreshGrid();
+        UI ui = event.getUI();
+        leaveRegistration = ui.addBeforeLeaveListener(beforeLeaveEvent -> {
+            if (isAttached() && hasUnsavedContent()) {
+                BeforeLeaveEvent.ContinueNavigationAction action = beforeLeaveEvent.postpone();
+                showLeaveDialog(action);
+            }
+        });
+        addDetachListener(e -> leaveRegistration.remove());
+    }
+
+    private void sendMessage() {
+        clearError(name);
+        clearError(email);
+        clearError(message);
+
+        boolean valid = true;
+
+        String nameValue = trimToEmpty(name.getValue());
+        if (nameValue.isEmpty()) {
+            markInvalid(name, ERR_NAME_REQUIRED);
+            valid = false;
+        }
+
+        String emailValue = trimToEmpty(email.getValue());
+        String phoneValue = trimToEmpty(phone.getValue());
+        if (!emailValue.isEmpty() && !isValidEmail(emailValue)) {
+            markInvalid(email, ERR_INVALID_EMAIL);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, ERR_EMAIL_OR_PHONE);
+            valid = false;
+        }
+
+        String messageValue = message.getValue() == null ? "" : message.getValue();
+        if (messageValue.isBlank()) {
+            markInvalid(message, ERR_MESSAGE_REQUIRED);
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            markInvalid(message, ERR_MESSAGE_TOO_LONG);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        Message sent = new Message(nameValue, emailValue, phoneValue, messageValue.trim());
+        MessageStore.add(sent);
+        refreshGrid();
+        new Notification("Message sent").open();
+        clearForm();
+        sendButton.setEnabled(false);
+    }
+
+    private void clearForm() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearError(name);
+        clearError(email);
+        clearError(message);
+    }
+
+    private void refreshGrid() {
+        grid.setDataProvider(new ListDataProvider<>(MessageStore.all()));
+    }
+
+    private boolean hasUnsavedContent() {
+        return hasContent(name) || hasContent(email) || hasContent(phone) || hasContent(message);
+    }
+
+    private static boolean hasContent(HasValue<?, String> field) {
+        return field.getValue() != null && !field.getValue().isEmpty();
+    }
+
+    private static String trimToEmpty(String value) {
+        return value == null ? "" : value.trim();
+    }
+
+    private static boolean isValidEmail(String value) {
+        return value != null && EMAIL.matcher(value).matches();
+    }
+
+    private static void markInvalid(HasValidation field, String message) {
+        field.setErrorMessage(message);
+        field.setInvalid(true);
+    }
+
+    private static void clearError(HasValidation field) {
+        field.setErrorMessage(null);
+        field.setInvalid(false);
+    }
+
+    private void showLeaveDialog(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsaved changes");
+        dialog.add(new Paragraph("You have unsaved changes. Leave and discard them?"));
+
+        Button keep = new Button("Keep editing", e -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+
+        HorizontalLayout buttons = new HorizontalLayout(keep, discard);
+        dialog.add(buttons);
+        dialog.open();
+    }
+}
