+package com.example;
+
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.server.VaadinSession;
+
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Keeps the list of sent messages for the current session. The list is newest
+ * first so that the most recently sent message is always the first row.
+ */
+public final class MessageStore {
+
+    private static final String KEY = MessageStore.class.getName() + ".messages";
+
+    private MessageStore() {
+    }
+
+    private static VaadinSession session() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            UI ui = UI.getCurrent();
+            if (ui != null) {
+                session = ui.getSession();
+            }
+        }
+        return session;
+    }
+
+    public static List<Message> all() {
+        VaadinSession session = session();
+        if (session == null) {
+            return new ArrayList<>();
+        }
+        synchronized (session) {
+            @SuppressWarnings("unchecked")
+            List<Message> messages = (List<Message>) session.getAttribute(KEY);
+            if (messages == null) {
+                messages = new ArrayList<>();
+                session.setAttribute(KEY, messages);
+            }
+            return messages;
+        }
+    }
+
+    public static void add(Message message) {
+        all().add(0, message);
+    }
+}
